import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const neuronApi = createApi({
    reducerPath: 'neuronApi',
    tagTypes: ['currentNeuron'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        // 404 — поточного нейрона немає.
        getCurrentNeuron: builder.query({
            query: () => ({
                url: '/neurons/current',
                method: RequestMethods.GET,
            }),
            providesTags: ['currentNeuron'],
        }),
    }),
});
export const { useGetCurrentNeuronQuery, } = neuronApi;
